/**
 * OpenCode V2 server plugin for the GUI-only product: it starts the shared
 * dashboard runtime, attaches the typed dashboard RPC transport, and keeps the
 * credential and quota-reset retry lifecycle working. Inherited terminal
 * surfaces (commands, tool, the TUI quota RPC and report hooks) are retained in
 * their source modules but are not registered by this product.
 */
import { randomUUID } from "node:crypto";
import { Plugin } from "@opencode/plugin";
import { startDashboard } from "./gui/lifecycle.js";
import { scrubLogReason } from "./gui/log.js";
import { registerDashboardRpc } from "./gui/rpc.js";
import { observeAnthropicApiResponse } from "./lib/anthropic-api-rate-limits.js";
import { projectOpenCodeCacheObserverEvent } from "./lib/cache-observer-ingestion.js";
import { readClaudeObservedTtl } from "./lib/claude-agent-transcript-ttl.js";
import { createClaudeAgentTtlTracker } from "./lib/claude-agent-ttl-tracker.js";
import { resolveOpenCodeLocationRoots } from "./lib/config-file-utils.js";
import { bindCredentialSource, createIntegrationCredentialSource, notifyCredentialsChanged, scrubCredentialErrorText, } from "./lib/opencode-auth.js";
import { OpencodeWarmingRefreshTracker } from "./lib/opencode-warming-refresh.js";
import { createQuotaAutoResumption } from "./lib/quota-auto-resume.js";
import { collectQuotaWindows, probeQuotaForModelState, resolveQuotaResetRetryDelayMs, } from "./lib/quota-retry-wait.js";
/** An error as one line that is safe to log: tokens redacted, at most 120 characters. */
function logReason(error) {
    return scrubCredentialErrorText(error instanceof Error ? error.message : String(error));
}
const MAX_PENDING_CACHE_OBSERVER_EVENTS = 512;
const MAX_SAMPLED_SESSIONS = 1_024;
const HOST_EVENT_RECONNECT_DELAY_MS = 1_000;
export const QuotaToastPlugin = Plugin.define({
    id: "opencode-quota-gui",
    async setup(ctx) {
        const roots = resolveOpenCodeLocationRoots(ctx.location.directory);
        // The quota collector accepts a small V1-shaped configuration client. V2
        // does not expose a mutable global config to plugins; runtime settings are
        // read from the canonical GUI config file by the collector.
        const client = {
            integration: { list: () => ctx.integration.list() },
            config: {
                get: async () => ({ data: {} }),
                providers: async () => ({
                    data: {
                        providers: (await ctx.provider.list()).data.map((provider) => ({ id: provider.id })),
                    },
                }),
            },
        };
        // With waitForQuotaReset on, a request that hit a provider limit is retried after the
        // used-up quota window resets. Any failure keeps OpenCode's own retry decision.
        const retryHost = { client, roots };
        await ctx.session.hook("retry", async (event) => {
            try {
                const delay = await resolveQuotaResetRetryDelayMs(retryHost, event);
                if (delay !== undefined)
                    event.decision = { retry: true, delay };
            }
            catch (error) {
                console.warn(`[opencode-quota-gui] retry hook failed: ${logReason(error)}`);
            }
        });
        // With autoResumeOnQuotaRecovery on (default off), a session that terminally failed on a
        // provider quota limit gets one `continue` prompt after the failed route's exhausted window
        // is observed as reset for the same verified identity. In-process timers only: a plugin
        // restart drops a pending resume.
        const autoResume = createQuotaAutoResumption({
            session: ctx.session,
            probe: async (model) => {
                const result = await probeQuotaForModelState(retryHost, model, (config) => config.autoResumeOnQuotaRecovery, { includeProviderScope: true });
                if (result.state === "disabled")
                    return { kind: "disabled" };
                if (result.state === "unsupported")
                    return { kind: "unsupported" };
                if (result.state === "unavailable")
                    return { kind: "absent" };
                const collection = collectQuotaWindows(result.probe.providerResults.map((entry) => entry.result), result.probe.binding, {
                    primaryAccountOnly: true,
                    // The controller keeps this model-scoped row only for a Fable failed model.
                    includeNamedWindows: ["named:Fable weekly"],
                });
                return collection ? { kind: "collection", collection } : { kind: "absent" };
            },
            log: (message) => console.warn(`[opencode-quota-gui] ${message}`),
        });
        // A user-submitted prompt suppresses a pending auto-resume; our own prompt carries the marker.
        await ctx.session.hook("prompt", (event) => {
            try {
                autoResume.onPrompt(event);
            }
            catch {
                // Pending-resume tracking must never interfere with a prompt.
            }
        });
        const warming = new OpencodeWarmingRefreshTracker();
        await ctx.session.hook("model.request", (event) => {
            try {
                warming.onModelRequest(event, Date.now());
            }
            catch {
                // Observation must never interfere with a request.
            }
        });
        // Read-only and synchronous: records allowlisted rate-limit headers from API-key Messages
        // responses for the Anthropic API card. It never alters, delays or throws into the request.
        await ctx.session.hook("http.response", (event) => {
            observeAnthropicApiResponse({ request: event.request, response: event.response });
        });
        // Owner-approved per-session approximation (not per-request proof): the host shares no
        // per-invocation id between `model.request` and `session.step.started`, and connections
        // rarely change, so the active OpenAI connection METHOD is sampled once per session — on
        // its `session.created` event, or on its first step for a session that predates this
        // plugin — and reused for that session's OpenAI steps. A lookup still pending (or failed)
        // leaves the step without a method, i.e. the conservative 5-minute TTL fallback; relayed
        // steps are never rewritten and a mid-session credential change is not reflected.
        // Only the allowlisted method is kept; credential values, ids and labels are never read.
        const openaiMethodBySession = new Map();
        const sampleOpenAiMethod = (sessionID) => {
            if (typeof sessionID !== "string" || sessionID === "")
                return;
            if (openaiMethodBySession.has(sessionID))
                return;
            if (openaiMethodBySession.size >= MAX_SAMPLED_SESSIONS) {
                const oldest = openaiMethodBySession.keys().next().value;
                if (oldest !== undefined)
                    openaiMethodBySession.delete(oldest);
            }
            const entry = {};
            openaiMethodBySession.set(sessionID, entry);
            void (async () => {
                try {
                    const connection = await ctx.integration.connection.active("openai");
                    const method = connection?.type === "credential" ? connection.method : undefined;
                    if (method === "oauth" || method === "key" || method === "external") {
                        entry.method = method;
                    }
                }
                catch {
                    // Unavailable metadata keeps the 5-minute fallback.
                }
            })();
        };
        // Every login read in this process goes through this location's `ctx.integration`. Bound
        // last, so a setup that fails part way leaves no binding behind. OpenCode routes the
        // retained hooks only after setup, so no read comes earlier.
        const unbindCredentialSource = bindCredentialSource(createIntegrationCredentialSource(ctx.integration));
        let dashboardRpc;
        let cacheObserverEmitChain = Promise.resolve();
        const pendingCacheObserverEvents = [];
        let pendingCacheObserverEventsDropped = false;
        let pendingHostEventObservedAtMs;
        const cacheObserverRelayAbort = new AbortController();
        let cacheObserverEmitWorkerRunning = false;
        const hostEventSourceBinding = randomUUID();
        let hostEventSourceState = "unverified";
        const readHostEventSourceState = () => hostEventSourceState;
        async function waitForHostEventReconnect(signal) {
            if (signal.aborted)
                return;
            await new Promise((resolve) => {
                let timer;
                const finish = () => {
                    if (timer !== undefined)
                        clearTimeout(timer);
                    signal.removeEventListener("abort", finish);
                    resolve();
                };
                timer = setTimeout(finish, HOST_EVENT_RECONNECT_DELAY_MS);
                signal.addEventListener("abort", finish, { once: true });
                if (signal.aborted)
                    finish();
            });
        }
        async function emitCacheObserverEventNow(registration, pending) {
            const { signal } = cacheObserverRelayAbort;
            if (signal.aborted)
                return;
            const emission = Promise.resolve()
                .then(() => {
                if (signal.aborted)
                    return;
                return registration.events.emit("invalidated", {
                    topic: "cache.observer",
                    at: pending.at,
                    cacheObserverEvent: pending.event,
                });
            })
                .then(() => undefined, () => undefined);
            if (signal.aborted)
                return;
            await new Promise((resolve) => {
                const finish = () => {
                    signal.removeEventListener("abort", finish);
                    resolve();
                };
                signal.addEventListener("abort", finish, { once: true });
                void emission.then(finish);
            });
        }
        async function drainCacheObserverEvents() {
            try {
                while (!cacheObserverRelayAbort.signal.aborted) {
                    if (pendingCacheObserverEventsDropped) {
                        pendingCacheObserverEventsDropped = false;
                        const registration = dashboardRpc;
                        if (!registration)
                            continue;
                        const gapAt = Date.now();
                        await emitCacheObserverEventNow(registration, {
                            at: gapAt,
                            event: {
                                type: "source.status",
                                created: gapAt,
                                data: { state: "unavailable", sourceBinding: hostEventSourceBinding },
                            },
                        });
                        if (hostEventSourceState === "observed")
                            pendingHostEventObservedAtMs = gapAt;
                        continue;
                    }
                    const pending = pendingCacheObserverEvents.shift();
                    if (!pending) {
                        const observedAt = pendingHostEventObservedAtMs;
                        if (observedAt === undefined)
                            break;
                        pendingHostEventObservedAtMs = undefined;
                        if (hostEventSourceState !== "observed")
                            continue;
                        const registration = dashboardRpc;
                        if (registration) {
                            await emitCacheObserverEventNow(registration, {
                                at: observedAt,
                                event: {
                                    type: "source.status",
                                    created: observedAt,
                                    data: { state: "observed", sourceBinding: hostEventSourceBinding },
                                },
                            });
                        }
                        continue;
                    }
                    const registration = dashboardRpc;
                    if (registration)
                        await emitCacheObserverEventNow(registration, pending);
                }
            }
            finally {
                cacheObserverEmitWorkerRunning = false;
            }
        }
        const startCacheObserverEmitWorker = () => {
            if (!dashboardRpc ||
                cacheObserverRelayAbort.signal.aborted ||
                cacheObserverEmitWorkerRunning) {
                return;
            }
            cacheObserverEmitWorkerRunning = true;
            cacheObserverEmitChain = drainCacheObserverEvents().catch(() => undefined);
        };
        const emitCacheObserverEvent = (event, at) => {
            if (cacheObserverRelayAbort.signal.aborted)
                return;
            if (pendingCacheObserverEvents.length >= MAX_PENDING_CACHE_OBSERVER_EVENTS) {
                pendingCacheObserverEvents.shift();
                pendingCacheObserverEventsDropped = true;
            }
            pendingCacheObserverEvents.push({ at, event });
            startCacheObserverEmitWorker();
        };
        const publishHostEventSourceState = (state, at) => {
            if (hostEventSourceState === state)
                return;
            hostEventSourceState = state;
            if (state !== "observed")
                pendingHostEventObservedAtMs = undefined;
            emitCacheObserverEvent({
                type: "source.status",
                created: at,
                data: { state, sourceBinding: hostEventSourceBinding },
            }, at);
        };
        const claudeTtl = createClaudeAgentTtlTracker({
            directory: ctx.location.directory,
            read: readClaudeObservedTtl,
            emit: emitCacheObserverEvent,
        });
        // Reuse the existing host stream for credential invalidation and narrowly projected cache
        // evidence. No Native-side OpenCode event subscription is opened.
        const hostEvents = new AbortController();
        void (async () => {
            const { signal } = hostEvents;
            while (!signal.aborted) {
                try {
                    for await (const event of ctx.event.subscribe({ signal })) {
                        if (signal.aborted)
                            return;
                        if (readHostEventSourceState() !== "observed") {
                            publishHostEventSourceState("observed", typeof event.created === "number" && Number.isFinite(event.created)
                                ? event.created
                                : Date.now());
                        }
                        if (event.type === "credential.updated" || event.type === "credential.switched") {
                            notifyCredentialsChanged();
                        }
                        try {
                            autoResume.handleEvent(event);
                        }
                        catch {
                            // Resume tracking is observation only; never break the host event stream.
                        }
                        // The Started event's model identity is available before invocation completion. Do not
                        // enrich it from model.list here: that mutable catalog may no longer match dispatch.
                        const sessionID = event.data?.sessionID;
                        if (event.type === "session.created")
                            sampleOpenAiMethod(sessionID);
                        else if (event.type === "session.deleted" && typeof sessionID === "string") {
                            openaiMethodBySession.delete(sessionID);
                        }
                        let cacheObserverEvent = projectOpenCodeCacheObserverEvent(event);
                        if (cacheObserverEvent?.type === "session.step.started" &&
                            cacheObserverEvent.data.model.providerID === "openai") {
                            sampleOpenAiMethod(cacheObserverEvent.data.sessionID);
                            const method = openaiMethodBySession.get(cacheObserverEvent.data.sessionID)?.method;
                            if (method !== undefined) {
                                cacheObserverEvent = {
                                    ...cacheObserverEvent,
                                    data: { ...cacheObserverEvent.data, connectionMethod: method },
                                };
                            }
                        }
                        if (cacheObserverEvent !== undefined &&
                            typeof event.created === "number" &&
                            Number.isFinite(event.created) &&
                            event.created >= 0) {
                            emitCacheObserverEvent(cacheObserverEvent, event.created);
                        }
                        claudeTtl.observe(event, cacheObserverEvent);
                        if (event.type === "session.step.started")
                            warming.onStepStarted(event);
                        else if (event.type === "session.step.ended")
                            warming.onStepEnded(event);
                        else if (event.type === "session.usage.updated") {
                            const refresh = warming.onUsageUpdated(event);
                            if (refresh !== undefined) {
                                emitCacheObserverEvent({ type: "session.cache.warming", data: refresh }, Date.now());
                            }
                        }
                    }
                    if (signal.aborted)
                        return;
                    throw new Error("host event stream ended");
                }
                catch (error) {
                    if (signal.aborted)
                        return;
                    if (readHostEventSourceState() !== "unavailable") {
                        publishHostEventSourceState("unavailable", Date.now());
                    }
                    console.warn(`[opencode-quota-gui] host event subscription failed; retrying: ${logReason(error)}`);
                    await waitForHostEventReconnect(signal);
                }
            }
        })();
        // The dashboard host binds last — after the retry hook and the credential binding — and it
        // never fails setup: every dashboard error stays a controlled log line and an `unavailable`
        // lease (spec §4.3). The first owner workspace supplies the config import root, and the
        // settings store reads the global canonical config. Binding is all that happens here; the
        // first snapshot is computed on the first request.
        let dashboardLease;
        try {
            // Older hosts may not supply `ctx.app` at runtime; an absent or empty
            // version lets the lifecycle use its bounded `opencode --version` probe.
            const hostVersion = ctx.app?.version;
            dashboardLease = await startDashboard({
                client,
                workspaceRoot: ctx.location.directory,
                ...(hostVersion !== undefined ? { hostVersion } : {}),
            });
        }
        catch (error) {
            console.warn(`[opencode-quota-gui] dashboard unavailable: ${logReason(error)}`);
        }
        // Attach the native RPC transport to the same host runtime the web
        // transport receives. It is available when web is disabled or its bind
        // failed, and it never constructs another source/snapshot/service.
        if (dashboardLease?.runtime && ctx.rpc) {
            try {
                dashboardRpc = await registerDashboardRpc(ctx.rpc, dashboardLease.runtime, {
                    location: ctx.location,
                    onWatchSnapshot: (attemptNonce) => {
                        const at = Date.now();
                        emitCacheObserverEvent({
                            type: "source.status",
                            created: at,
                            data: {
                                state: readHostEventSourceState(),
                                attemptNonce,
                                sourceBinding: hostEventSourceBinding,
                            },
                        }, at);
                    },
                });
                startCacheObserverEmitWorker();
            }
            catch {
                console.warn(`[opencode-quota-gui] dashboard RPC unavailable: registration-failed`);
            }
        }
        return async () => {
            hostEvents.abort();
            autoResume.dispose();
            claudeTtl.dispose();
            openaiMethodBySession.clear();
            pendingCacheObserverEvents.length = 0;
            publishHostEventSourceState("stopped", Date.now());
            unbindCredentialSource();
            pendingCacheObserverEvents.length = 0;
            pendingCacheObserverEventsDropped = false;
            cacheObserverRelayAbort.abort();
            await cacheObserverEmitChain;
            if (dashboardRpc) {
                try {
                    await dashboardRpc.dispose();
                }
                catch (error) {
                    console.warn(`[opencode-quota-gui] dashboard RPC stop failed: ${scrubLogReason(error instanceof Error ? error.message : String(error))}`);
                }
            }
            if (dashboardLease) {
                try {
                    await dashboardLease.dispose();
                }
                catch (error) {
                    console.warn(`[opencode-quota-gui] dashboard stop failed: ${logReason(error)}`);
                }
            }
        };
    },
});
